import pty,os,sys,fcntl,termios,struct
def run(args, cols):
    pid, fd = pty.fork()
    if pid==0:
        os.execvpe('./executable', ['./executable']+args, dict(os.environ))
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', 24, cols, 0, 0))
    out=b''
    try:
        while True:
            d=os.read(fd,4096)
            if not d: break
            out+=d
    except OSError: pass
    os.waitpid(pid,0)
    return out.decode()
for cols in [40, 60, 80, 200]:
    print('=== cols', cols)
    print(run(['--help'], cols))
" | head -80"}

