import math,subprocess
PI=math.pi
def variants(u,i):
    return {
     'A': PI*i/(2*u),
     'B': (PI/(2*u))*i,
     'C': PI*i/2/u,
     'D': (PI/2)*(i/u),
     'E': i*PI/(2*u),
     'F': (i/(2*u))*PI,
     'G': PI*(i/u)/2,
     'H': (PI*i)/(2*u),
     'I': (2*math.pi)*(i/(4*u)),
     'J': math.asin(1.0)*0 + PI/2*(i/u),
    }
targets={}
bad={}
for u in range(1,40):
    o=subprocess.run(['./executable','-u',str(u),'-p','20'],capture_output=True).stdout.decode().split(',')
    got=[x for x in o if x]
    for i in range(u):
        # target double from hx output: parse the decimal exactly
        target=float(got[i])
        for k,v in variants(u,i).items():
            if math.sin(v)!=target:
                bad[k]=bad.get(k,0)+1
print(bad)
""}

