//! Function wave output.

use std::io::{self, Write};

/// Number of wave values rendered on a single output line.
const LINE_LEN: usize = 10;

/// Default number of decimal places used when `--places` was omitted.
pub const DEFAULT_PLACES: u64 = 4;

/// Emit the `--func` wave: `sin(i / len * FRAC_PI_2)` for `i` in `0..len`.
///
/// Every value is followed by a comma; a line break is inserted after every
/// `LINE_LEN` values and the very end of the output is terminated by a line
/// break as well.
pub fn wave(len: u64, places: u64) -> io::Result<()> {
    let stdout = io::stdout();
    let mut out = stdout.lock();

    let half = std::f64::consts::FRAC_PI_2;
    for index in 0..len {
        let value = (index as f64 / len as f64 * half).sin();
        let rendered = format!("{:.*$}", value, places as usize);
        write!(out, "{},", rendered)?;
        if (index + 1) % LINE_LEN as u64 == 0 {
            writeln!(out)?;
        }
    }
    writeln!(out)
}
