//! hx - Futuristic take on hexdump, made in Rust.
//!
//! The crate implements the command line front end, the input reader and the
//! two output renderers (hex dump and source code array) of the tool.

pub mod function_output;

use std::io::{self, Read, Write};

/// Program version reported by `--version`.
const VERSION: &str = "hx 0.7.0";

/// First help section printed by `--help`.
const ABOUT: &str = "Futuristic take on hexdump, made in Rust.";

/// Width of a placeholder octet cell (a cell that has no byte in it).
const EMPTY_CELL: usize = 5;

/// Minimum amount of hexadecimal digits used to render an offset.
const MIN_ADDR_DIGITS: usize = 6;

/// Number of wave values printed on a single `--func` output line.
const FUNC_LINE_LEN: u64 = 10;

/// Octet rendering styles accepted by `--format`.
#[derive(Clone, Copy, PartialEq)]
enum OctetFormat {
    Octal,
    LowerHex,
    UpperHex,
    Binary,
}

/// Source code array styles accepted by `--array`.
#[derive(Clone, Copy, PartialEq)]
enum ArrayFormat {
    Rust,
    C,
    Golang,
    Python,
    Kotlin,
    Java,
    Swift,
    Fsharp,
}

/// Description of a single command line option.
struct OptDef {
    short: char,
    long: &'static str,
    /// Placeholder of the option value, `None` when the option is a flag.
    value: Option<&'static str>,
    /// Accepted values, `None` when any string is accepted.
    possible: Option<&'static [&'static str]>,
}

/// Index of every option inside [`OPTS`].
const IDX_COLS: usize = 0;
const IDX_LEN: usize = 1;
const IDX_FORMAT: usize = 2;
const IDX_COLOR: usize = 3;
const IDX_ARRAY: usize = 4;
const IDX_FUNC: usize = 5;
const IDX_PLACES: usize = 6;
const IDX_PREFIX: usize = 7;
const IDX_HELP: usize = 8;
const IDX_VERSION: usize = 9;

/// The option table, in declaration order.
const OPTS: [OptDef; 10] = [
    OptDef { short: 'c', long: "cols", value: Some("columns"), possible: None },
    OptDef { short: 'l', long: "len", value: Some("len"), possible: None },
    OptDef {
        short: 'f',
        long: "format",
        value: Some("format"),
        possible: Some(&["o", "x", "X", "b"]),
    },
    OptDef {
        short: 't',
        long: "color",
        value: Some("color"),
        possible: Some(&["0", "1"]),
    },
    OptDef {
        short: 'a',
        long: "array",
        value: Some("array_format"),
        possible: Some(&["r", "c", "g", "p", "k", "j", "s", "f"]),
    },
    OptDef { short: 'u', long: "func", value: Some("func_length"), possible: None },
    OptDef {
        short: 'p',
        long: "places",
        value: Some("func_places"),
        possible: None,
    },
    OptDef {
        short: 'r',
        long: "prefix",
        value: Some("prefix"),
        possible: Some(&["0", "1"]),
    },
    OptDef { short: 'h', long: "help", value: None, possible: None },
    OptDef { short: 'V', long: "version", value: None, possible: None },
];

/// Body of the `Options:` block of `--help`.
const OPT_HELP: &str = "\
  -c, --cols <columns>        Set column length
  -l, --len <len>             Set <len> bytes to read
  -f, --format <format>       Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b) [possible values: o, x, X, b]
  -t, --color <color>         Set color tint terminal output. 0 to disable, 1 to enable [possible values: 0, 1]
  -a, --array <array_format>  Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f) [possible values: r, c, g, p, k, j, s, f]
  -u, --func <func_length>    Set function wave length
  -p, --places <func_places>  Set function wave output decimal places
  -r, --prefix <prefix>       Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable [possible values: 0, 1]
  -h, --help                  Print help
  -V, --version               Print version
";

/// Command line parsing failure.
enum CliError {
    /// An argument that does not belong to the command was found.
    Unknown {
        arg: String,
        tip: Option<String>,
        usage: String,
    },
    /// An option value was expected but not supplied.
    Missing {
        spec: String,
        possible: Option<&'static [&'static str]>,
    },
    /// An option value is not one of the accepted values.
    InvalidValue {
        value: String,
        spec: String,
        possible: &'static [&'static str],
    },
    /// An option was supplied more than once.
    Duplicate { spec: String },
}

/// Renders the `--long <value>` form of an option.
fn spec(index: usize) -> String {
    let def = &OPTS[index];
    match def.value {
        Some(name) => format!("--{} <{}>", def.long, name),
        None => format!("--{}", def.long),
    }
}

/// Reports a command line failure and terminates the process.
fn fail(error: &CliError) -> ! {
    match error {
        CliError::Unknown { arg, tip, usage } => {
            eprint!("error: unexpected argument '{}' found\n", arg);
            if let Some(text) = tip {
                eprint!("\n  tip: {}\n", text);
            }
            eprint!("\nUsage: {}\n", usage);
        }
        CliError::Missing { spec, possible } => {
            eprint!("error: a value is required for '{}' but none was supplied\n", spec);
            if let Some(values) = possible {
                eprint!("  [possible values: {}]\n", values.join(", "));
            }
        }
        CliError::InvalidValue { value, spec, possible } => {
            eprint!("error: invalid value '{}' for '{}'\n", value, spec);
            eprint!("  [possible values: {}]\n", possible.join(", "));
            if let Some(text) = similar_value(value, possible) {
                eprint!("\n  tip: a similar value exists: '{}'\n", text);
            }
        }
        CliError::Duplicate { spec } => {
            eprint!("error: the argument '{}' cannot be used multiple times\n", spec);
            eprint!("\nUsage: {}\n", default_usage());
        }
    }
    eprint!("\nFor more information, try '--help'.\n");
    std::process::exit(2);
}

/// Default usage line, without the leading `Usage: ` label.
fn default_usage() -> String {
    format!("{} [OPTIONS] [INPUTFILE]", program_name())
}

/// Name the command was invoked with.
fn program_name() -> String {
    match std::env::args_os().next() {
        Some(arg) => match std::path::Path::new(&arg).file_name() {
            Some(name) => name.to_string_lossy().into_owned(),
            None => arg.to_string_lossy().into_owned(),
        },
        None => String::from("hx"),
    }
}

/// Jaro similarity of two strings.
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let window = (std::cmp::max(a.len(), b.len()) / 2).saturating_sub(1);
    let mut a_hit = vec![false; a.len()];
    let mut b_hit = vec![false; b.len()];
    let mut matches = 0usize;
    for (i, ca) in a.iter().enumerate() {
        let low = i.saturating_sub(window);
        let high = std::cmp::min(b.len() - 1, i + window);
        for j in low..=high {
            if !b_hit[j] && *ca == b[j] {
                a_hit[i] = true;
                b_hit[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if !a_hit[i] {
            continue;
        }
        while !b_hit[k] {
            k += 1;
        }
        if a[i] != b[k] {
            transpositions += 1;
        }
        k += 1;
    }
    transpositions /= 2;
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - transpositions as f64) / m) / 3.0
}

/// Jaro-Winkler similarity of two strings.
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let mut confidence = jaro(a, b);
    if confidence > 0.7 {
        let mut prefix = 0usize;
        for (ca, cb) in a.chars().zip(b.chars()) {
            if ca != cb {
                break;
            }
            prefix += 1;
            if prefix == 4 {
                break;
            }
        }
        confidence += 0.1 * prefix as f64 * (1.0 - confidence);
    }
    confidence
}

/// Closest candidate of `candidates` for `value`, when it is close enough.
fn did_you_mean(value: &str, candidates: &[&str]) -> Option<String> {
    let mut scored: Vec<(f64, &str)> = candidates
        .iter()
        .map(|c| (jaro_winkler(value, c), *c))
        .filter(|(confidence, _)| *confidence > 0.7)
        .collect();
    scored.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    scored.reverse();
    scored.first().map(|(_, name)| String::from(*name))
}

/// Similar accepted value of an option, used by the invalid value report.
fn similar_value(value: &str, possible: &'static [&'static str]) -> Option<String> {
    did_you_mean(value, possible)
}

/// Similar option of the command, used by the unknown argument report.
fn similar_option(name: &str) -> Option<(usize, String)> {
    let mut candidates: Vec<&str> = Vec::new();
    let mut indices: Vec<usize> = Vec::new();
    for (index, def) in OPTS.iter().enumerate() {
