/// Reports an unknown argument and terminates the process.
fn fail_unknown(arg: String, suggestion: Option<(usize, String)>) -> ! {
    let tip = match suggestion {
        Some((_, spec)) => format!("a similar argument exists: '{}'", spec),
        None => format!("to pass '{}' as a value, use '-- {}'", arg, arg),
    };
    let usage = match suggestion {
        Some((index, spec)) => format!("{} {} [INPUTFILE]", program_name(), spec),
        None => default_usage(),
    };
    fail(&CliError::Unknown { arg, tip, usage })
}

/// Long option matching `name`, if any.
fn find_long(name: &str) -> Option<usize> {
    OPTS.iter().position(|def| def.long == name)
}

/// Short option matching `short`, if any.
fn find_short(short: char) -> Option<usize> {
    OPTS.iter().position(|def| def.short == short)
}

/// Stores an option value, reporting failures immediately.
fn store(index: usize, value: Option<String>, values: &mut Vec<Option<String>>) {
    let value = match value {
        Some(value) => value,
        None => fail(&CliError::Missing {
            spec: spec(index),
            possible: OPTS[index].possible,
        }),
    };
    if values[index].is_some() {
        fail(&CliError::Duplicate { spec: spec(index) });
    }
    if let Some(possible) = OPTS[index].possible {
        if value.is_empty() {
            fail(&CliError::Missing {
                spec: spec(index),
                possible: OPTS[index].possible,
            });
        }
        if !possible.iter().any(|candidate| *candidate == value) {
            fail(&CliError::InvalidValue {
                value,
                spec: spec(index),
                possible,
            });
        }
    }
    values[index] = Some(value);
}

/// Stores the value of an option that was waiting for it.
fn resolve(pending: &mut Option<(usize, Option<String>)>, values: &mut Vec<Option<String>>) {
    if let Some((index, value)) = pending.take() {
        store(index, value, values);
    }
}

/// Prints the help text and terminates the process.
fn print_help() -> ! {
    print!(
        "{}\n\n\nUsage: {} [OPTIONS] [INPUTFILE]\n\nArguments:\n  [INPUTFILE]  Pass file path as an argument, or input data may be passed via stdin\n\nOptions:\n{}",
        ABOUT,
        program_name(),
        OPT_HELP
    );
    std::process::exit(0);
}

/// Prints the version and terminates the process.
fn print_version() -> ! {
    print!("{}\n", VERSION);
    std::process::exit(0);
}

/// Parses the command line.
fn parse() -> Config {
    let args: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect();
    let mut values: Vec<Option<String>> = vec![None; OPTS.len()];
    let mut pending: Option<(usize, Option<String>)> = None;
    let mut trailing = false;
    let mut positional: Option<String> = None;
    let mut index = 0usize;
    while index < args.len() {
        let token = args[index].clone();
        let flag_like = !trailing && token.starts_with('-') && token.len() > 1;
        if !flag_like {
            if let Some((opt, None)) = pending {
                pending = Some((opt, Some(token)));
                index += 1;
                continue;
            }
        }
        if flag_like {
            if token == "--" {
                resolve(&mut pending, &mut values);
                trailing = true;
                index += 1;
                continue;
            }
            if token.starts_with("--") {
                let body = &token[2..];
                let (name, attached) = match body.split_once('=') {
                    Some((name, value)) => (name, Some(String::from(value))),
                    None => (body, None),
                };
                let opt = match find_long(name) {
                    Some(opt) => opt,
                    None => fail_unknown(
                        format!("--{}", name),
                        similar_option(name),
                    ),
                };
                resolve(&mut pending, &mut values);
                if opt == IDX_HELP {
                    print_help();
                }
                if opt == IDX_VERSION {
                    print_version();
                }
                match attached {
                    Some(value) => store(opt, Some(value), &mut values),
                    None => pending = Some((opt, None)),
                }
            } else {
                let chars: Vec<char> = token[1..].chars().collect();
                let mut position = 0usize;
                while position < chars.len() {
                    let short = chars[position];
                    let opt = match find_short(short) {
                        Some(opt) => opt,
                        None => fail_unknown(format!("-{}", short), None),
                    };
                    resolve(&mut pending, &mut values);
                    if opt == IDX_HELP {
                        print_help();
                    }
                    if opt == IDX_VERSION {
                        print_version();
                    }
                    if OPTS[opt].value.is_some() {
                        let rest: String = chars[position + 1..].iter().collect();
                        if rest.is_empty() {
                            pending = Some((opt, None));
                        } else {
                            let value = match rest.strip_prefix('=') {
                                Some(value) => String::from(value),
                                None => rest,
                            };
                            store(opt, Some(value), &mut values);
                        }
                        break;
                    }
                    position += 1;
                }
            }
        } else {
            resolve(&mut pending, &mut values);
            if positional.is_some() {
                fail_unknown(token, None);
            }
            positional = Some(token);
        }
        index += 1;
    }
    resolve(&mut pending, &mut values);
    Config::from(values, positional)
}

/// Fully parsed command line.
struct Config {
    inputfile: Option<String>,
    cols: Option<String>,
    len: Option<String>,
    format: Option<OctetFormat>,
    color: Option<char>,
    array: Option<ArrayFormat>,
    func: Option<String>,
    places: Option<String>,
    prefix: Option<char>,
}

impl Config {
    fn from(values: Vec<Option<String>>, positional: Option<String>) -> Config {
        Config {
            inputfile: positional,
            cols: values[IDX_COLS].clone(),
            len: values[IDX_LEN].clone(),
            format: values[IDX_FORMAT]
                .as_deref()
                .and_then(|value| value.chars().next())
                .map(|short| match short {
                    'o' => OctetFormat::Octal,
                    'X' => OctetFormat::UpperHex,
                    'b' => OctetFormat::Binary,
                    _ => OctetFormat::LowerHex,
                }),
            color: values[IDX_COLOR]
                .as_deref()
                .and_then(|value| value.chars().next()),
            array: values[IDX_ARRAY]
                .as_deref()
                .and_then(|value| value.chars().next())
                .map(|short| match short {
                    'c' => ArrayFormat::C,
                    'g' => ArrayFormat::Golang,
                    'p' => ArrayFormat::Python,
                    'k' => ArrayFormat::Kotlin,
                    'j' => ArrayFormat::Java,
                    's' => ArrayFormat::Swift,
                    'f' => ArrayFormat::Fsharp,
                    _ => ArrayFormat::Rust,
                }),
            func: values[IDX_FUNC].clone(),
            places: values[IDX_PLACES].clone(),
            prefix: values[IDX_PREFIX]
                .as_deref()
                .and_then(|value| value.chars().next()),
        }
    }
}
