    inputfile: Option<String>,
    cols: Option<String>,
    len: Option<String>,
    format: Option<OctetFormat>,
    color: Option<char>,
    array: Option<ArrayFormat>,
    func: Option<String>,
    places: Option<String>,
    prefix: Option<char>,
}

impl Config {
    fn from(values: Vec<Option<String>>, positional: Option<String>) -> Config {
        Config {
            inputfile: positional,
            cols: values[IDX_COLS].clone(),
            len: values[IDX_LEN].clone(),
            format: values[IDX_FORMAT]
                .as_deref()
                .and_then(|value| value.chars().next())
                .map(|short| match short {
                    'o' => OctetFormat::Octal,
                    'X' => OctetFormat::UpperHex,
                    'b' => OctetFormat::Binary,
                    _ => OctetFormat::LowerHex,
                }),
            color: values[IDX_COLOR]
                .as_deref()
                .and_then(|value| value.chars().next()),
            array: values[IDX_ARRAY]
                .as_deref()
                .and_then(|value| value.chars().next())
                .map(|short| match short {
                    'c' => ArrayFormat::C,
                    'g' => ArrayFormat::Golang,
                    'p' => ArrayFormat::Python,
                    'k' => ArrayFormat::Kotlin,
                    'j' => ArrayFormat::Java,
                    's' => ArrayFormat::Swift,
                    'f' => ArrayFormat::Fsharp,
                    _ => ArrayFormat::Rust,
                }),
            func: values[IDX_FUNC].clone(),
            places: values[IDX_PLACES].clone(),
            prefix: values[IDX_PREFIX]
                .as_deref()
                .and_then(|value| value.chars().next()),
        }
    }
}
