/// Parses an integer command line value, reporting failures the way the
/// original tool does.
fn integer(short: char, long: &str, raw: &Option<String>) -> io::Result<Option<u64>> {
    let raw = match raw {
        Some(raw) => raw,
        None => return Ok(None),
    };
    match raw.parse::<u64>() {
        Ok(value) => Ok(Some(value)),
        Err(err) => {
            eprint!("{}, {} <integer> expected. {:?}\n", short, long, err);
            Err(io::Error::from(err))
        }
    }
}

/// Reads the whole input, honouring the optional `--len` limit.
fn read_to_limit(reader: &mut impl Read, limit: Option<u64>) -> io::Result<Vec<u8>> {
    let mut data: Vec<u8> = Vec::new();
    match limit {
        None => {
            reader.read_to_end(&mut data)?;
        }
        Some(mut remaining) => {
            let mut buffer = [0u8; 8192];
            while remaining > 0 {
                let want = std::cmp::min(remaining, buffer.len() as u64) as usize;
                match reader.read(&mut buffer[..want]) {
                    Ok(0) => break,
                    Ok(read) => {
                        data.extend_from_slice(&buffer[..read]);
                        remaining -= read as u64;
                    }
                    Err(err) if err.kind() == io::ErrorKind::Interrupted => continue,
                    Err(err) => return Err(err),
                }
            }
        }
    }
    Ok(data)
}

/// Decides whether the hex dump is colorized.
fn color_enabled(color: Option<char>) -> bool {
    match color {
        Some('1') => true,
        Some(_) => false,
        None => io::stdout().is_terminal() && !no_color_set(),
    }
}

