                if color {
                    format!("\x1b[38;5;{}m{}\x1b[0m", tint(byte), text)
                } else {
                    String::from(text)
                }
            }),
        }
    }
}

/// Emits a single hex dump row.
fn write_row<W: Write>(
    out: &mut W,
    offset: usize,
    bytes: &[u8],
    cols: usize,
    cells: &Cells,
) -> io::Result<()> {
    let mut line = String::with_capacity(bytes.len() * 8 + 16);
    line.push_str("0x");
    line.push_str(&address(offset));
    line.push_str(": ");
    for byte in bytes {
        line.push_str(&cells.octet[*byte as usize]);
    }
    if write!(out, "{}", line).is_err() {
        return Ok(());
    }
    if bytes.len() < cols {
        let width = (cols - bytes.len()).wrapping_mul(EMPTY_CELL);
        let padding = format!("{:w$}", "", w = width);
        if write!(out, "{}", padding).is_err() {
            return Ok(());
        }
    }
    let mut tail = String::with_capacity(bytes.len() * 4 + 1);
    for byte in bytes {
        tail.push_str(&cells.text[*byte as usize]);
    }
    tail.push('\n');
    if write!(out, "{}", tail).is_err() {
        return Ok(());
    }
    Ok(())
}

/// Renders the hexadecimal dump of `data`.
fn print_dump(
    data: &[u8],
    cols: usize,
    format: OctetFormat,
    prefix: bool,
    color: bool,
) -> io::Result<()> {
    let chunk = std::cmp::max(cols, 1);
    let cells = Cells::new(format, prefix, color);
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let mut offset = 0usize;
    while offset < data.len() {
        let end = std::cmp::min(offset.saturating_add(chunk), data.len());
        write_row(&mut out, offset, &data[offset..end], cols, &cells)?;
        offset = end;
    }
    if data.len() % chunk == 0 {
        write_row(&mut out, data.len(), &[], cols, &cells)?;
    }
    if write!(out, "   bytes: {}\n", data.len()).is_err() {
        return Ok(());
    }
    Ok(())
}

/// Header, footer, element suffix and element separator of an array style.
fn array_style(format: ArrayFormat) -> (&'static str, &'static str, &'static str, &'static str) {
    match format {
        ArrayFormat::Rust => ("let ARRAY: [u8; ", "];", "", ", "),
        ArrayFormat::C => ("unsigned char ARRAY[", "};", "", ", "),
        ArrayFormat::Golang => ("a := [", "}", "", ", "),
        ArrayFormat::Python => ("a = [", "]", "", ", "),
        ArrayFormat::Kotlin => ("val a = byteArrayOf(", ")", "", ", "),
        ArrayFormat::Java => ("byte[] a = new byte[]{", "};", "", ", "),
        ArrayFormat::Swift => ("let a: [UInt8] = [", "]", "", ", "),
        ArrayFormat::Fsharp => ("let a = [|", "|]", "uy", "; "),
    }
}

/// Renders `data` as a source code array literal.
fn print_array(data: &[u8], format: ArrayFormat, cols: usize) -> io::Result<()> {
    let chunk = std::cmp::max(cols, 1);
    let (header, footer, suffix, separator) = array_style(format);
    let stdout = io::stdout();
    let mut out = stdout.lock();
    if write!(out, "{}{}]\n", header, data.len()).is_err() {
        return Ok(());
    }
    let mut index = 0usize;
    while index < data.len() {
        if write!(out, "\n    ").is_err() {
            return Ok(());
        }
        let end = std::cmp::min(index.saturating_add(chunk), data.len());
        for byte in &data[index..end] {
            if write!(out, "0x{:02x}{}", byte, suffix).is_err() {
                return Ok(());
            }
            if index + 1 < data.len() && write!(out, "{}", separator).is_err() {
                return Ok(());
            }
            index += 1;
        }
    }
    if data.len() % chunk == 0 && write!(out, "\n    ").is_err() {
        return Ok(());
    }
    if write!(out, "\n{}\n", footer).is_err() {
        return Ok(());
    }
    Ok(())
}

/// Runs the tool, returning the failure of any step.
pub fn run() -> io::Result<()> {
    let config = parse();
    if config.func.is_some() {
        let places = integer('p', "--places", &config.places)?;
        let func = integer('u', "--func", &config.func)?;
        let func = func.unwrap_or(function_output::DEFAULT_PLACES);
        let places = places.unwrap_or(function_output::DEFAULT_PLACES);
        return function_output::wave(func, places);
    }
    let mut file = match &config.inputfile {
        Some(path) => Some(io::BufReader::new(std::fs::File::open(path)?)),
        None => None,
    };
    let cols = integer('c', "--cols", &config.cols)?;
    let limit = integer('l', "--len", &config.len)?;
    let data = match file.as_mut() {
        Some(reader) => read_to_limit(reader, limit)?,
        None => {
            let stdin = io::stdin();
            let mut lock = stdin.lock();
            read_to_limit(&mut lock, limit)?
