fn print_array(data: &[u8], format: ArrayFormat, cols: usize) -> io::Result<()> {
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let chunk = std::cmp::max(cols, 1);
    let (header, footer, suffix, sep) = match format { ... };
    if write!(out, "{}\n", header).is_err() { return Ok(()) }
    let mut index = 0usize;
    while index < data.len() {
        if write!(out, "\n    ").is_err() { return Ok(()) }
        let end = std::cmp::min(index.saturating_add(chunk), data.len());
        for i in index..end {
            if write!(out, "0x{:02x}{}", data[i], suffix).is_err() { return Ok(()) }
            if i + 1 < data.len() { if write!(out, "{}", sep).is_err() { return Ok(()) } }
        }
        index = end;
    }
    if data.len() % chunk == 0 { if write!(out, "\n    ").is_err() { return Ok(()) } }
    if write!(out, "\n{}\n", footer).is_err() { return Ok(()) }
    Ok(())
}
```

