{"command": "mkdir -p /tmp/cmp && ln -sf /workspace/target/debug/hx /tmp/cmp/executable && cat > /tmp/cmp_harness.py <<'PYEOF'
import subprocess, os, sys, pty, re

ORIG = "/workspace/executable"
MINE = "/tmp/cmp/executable"

def run(exe, args, stdin=b'', env=None, cwd=None, tty=False):
    e = dict(os.environ)
    if env: e.update(env)
    if tty:
        out = []
        pid, fd = pty.fork()
        if pid == 0:
            if cwd: os.chdir(cwd)
            try: os.execvpe(exe, [exe]+args, e)
            except Exception: os._exit(127)
        data=b''
        try:
            while True:
                d=os.read(fd,65536)
                if not d: break
                data+=d
        except OSError: pass
        os.waitpid(pid,0)
        return data
    p = subprocess.run([exe]+args, input=stdin, capture_output=True, env=e, cwd=cwd)
    return p.stdout, p.stderr, p.returncode

def compare(args, stdin=b'', env=None, cwd_orig='/workspace', cwd_mine='/tmp/cmp', tty=False, label=None):
    a = run(ORIG, args, stdin, env, cwd_orig, tty)
    b = run(MINE, args, stdin, env, cwd_mine, tty)
    if tty:
        if a != b:
            print("MISMATCH(tty)", label or args)
            print("  orig:", a[:300])
            print("  mine:", b[:300])
            return False
        return True
    ao, ae, ar = a
    bo, be, br = b
    ok = (ao == bo) and (ae == be) and (ar == br)
    if not ok:
        print("MISMATCH", label or args)
        if ao != bo:
            print("  stdout orig:", repr(ao[:400]))
            print("  stdout mine:", repr(bo[:400]))
        if ae != be:
            print("  stderr orig:", repr(ae[:400]))
            print("  stderr mine:", repr(be[:400]))
        if ar != br:
            print("  rc orig:", ar, "mine:", br)
    return ok
PYEOF
