//! Function wave output.
//!
//! The `--func` option replaces the hexadecimal dump with a sine wave. The
//! wave holds `len` values, value `i` being `sin(i / len * FRAC_PI_2)`, so
//! the wave rises from zero to one over the requested number of values.
//!
//! Every value is printed on its own, followed by a comma. A line break is
//! inserted after every ten values as well as at the very end of the output,
//! which means that even an empty wave is terminated by a line break. The
//! number of decimal places of every value is controlled by `--places` and
//! defaults to four when the option is missing.

use std::io::{self, Write};

/// Number of wave values printed on a single output line.
const LINE_LEN: usize = 10;

/// Number of decimal places used when `--places` was not given.
pub const DEFAULT_PLACES: u64 = 4;

/// Computes the `--func` wave of `len` values.
///
/// The wave holds `len` values. Value `i` is `sin(i / len * FRAC_PI_2)`, so
/// the wave rises from zero to one over the requested number of values. An
/// empty length produces an empty wave.
fn sine(len: u64) -> Vec<f64> {
    let half = std::f64::consts::FRAC_PI_2;
    let mut values: Vec<f64> = Vec::with_capacity(len as usize);
    for index in 0..len {
        values.push((index as f64 / len as f64 * half).sin());
    }
    values
}

/// Prints the `--func` wave of `len` values with `places` decimal places.
///
/// Every value is followed by a comma. A line break is written after every
/// [`LINE_LEN`] values and once more at the end of the output, so an empty
/// wave still ends with a line break. Writing stops with a panic when the
/// standard output cannot be written to.
pub fn wave(len: u64, places: u64) {
    let values = sine(len);
    let half = std::f64::consts::FRAC_PI_2;

    for index in 0..len {
        let value = values[index as usize];
        let rendered: String = format!("{:.prec$}", value, prec = places as usize);
        print!("{},", rendered);
        if (index + 1) % LINE_LEN as u64 == 0 {
            println!();
        }
    }
    println!();
}
