            fail(&CliError::Missing {
                spec: spec(index),
                possible: OPTS[index].possible,
            });
        }
        if !possible.iter().any(|candidate| *candidate == text) {
            fail(&CliError::InvalidValue {
                value: String::from(text),
                spec: spec(index),
                possible,
            });
        }
    }
    values[index] = Some(value);
}

/// Stores the value of an argument that was waiting for it.
fn resolve(
    pending: &mut Option<(usize, Option<Raw>)>,
    positional: &mut Option<Raw>,
    parsed: &mut bool,
    values: &mut Vec<Option<Raw>>,
) {
    if let Some((index, value)) = pending.take() {
        store(index, value, values);
    }
    if !*parsed {
        if let Some(raw) = positional.as_ref() {
            if raw.text().is_none() {
                fail_utf8();
            }
            *parsed = true;
        }
    }
}

/// Prints the help text and terminates the process.
fn print_help() -> ! { ... }

/// Prints the version and terminates the process.
fn print_version() -> ! { ... }

/// Parses the command line.
fn parse() -> Config {
    let args: Vec<OsString> = std::env::args_os().skip(1).collect();
    let mut values: Vec<Option<Raw>> = vec![None; OPTS.len()];
    let mut pending: Option<(usize, Option<Raw>)> = None;
    let mut positional: Option<Raw> = None;
    let mut positional_seen = false;
    let mut positional_parsed = false;
    let mut trailing = false;
    let mut index = 0usize;
    while index < args.len() {
        let token = args[index].clone();
        let bytes = token.as_os_str().as_bytes();
        let lossy = String::from_utf8_lossy(bytes).into_owned();
        let flag_like = !trailing && lossy.starts_with('-') && lossy.chars().count() > 1;
        if !flag_like {
            if let Some((opt, None)) = pending {
                pending = Some((opt, Some(Raw::new(bytes))));
                index += 1;
                continue;
            }
        }
        if flag_like {
            if lossy == "--" {
                resolve(&mut pending, &mut positional, &mut positional_parsed, &mut values);
                trailing = true;
                index += 1;
                continue;
            }
            if lossy.starts_with("--") {
                let body = &bytes[2..];
                let (name, value) = match body.iter().position(|byte| *byte == b'=') {
                    Some(split) => (&body[..split], Some(&body[split + 1..])),
                    None => (body, None),
                };
                let name = String::from_utf8_lossy(name).into_owned();
                let opt = match find_long(&name) {
                    Some(opt) => opt,
                    None => fail_unknown(format!("--{}", name), similar_option(&name)),
                };
                resolve(&mut pending, &mut positional, &mut positional_parsed, &mut values);
                if opt == IDX_HELP {
                    print_help();
                }
                if opt == IDX_VERSION {
                    print_version();
                }
                match value {
                    Some(value) => store(opt, Some(Raw::new(value)), &mut values),
                    None => pending = Some((opt, None)),
                }
            } else {
                let rest = &bytes[1..];
                let mut position = 0usize;
                while position < rest.len() {
                    let (short, width) = match decode(&rest[position..]) {
                        Some(decoded) => decoded,
                        None => fail_unknown(lossy.clone(), None),
                    };
                    let opt = match find_short(short) {
                        Some(opt) => opt,
                        None => fail_unknown(format!("-{}", short), None),
                    };
                    resolve(&mut pending, &mut positional, &mut positional_parsed, &mut values);
                    if opt == IDX_HELP {
                        print_help();
                    }
                    if opt == IDX_VERSION {
                        print_version();
                    }
                    if OPTS[opt].value.is_some() {
                        let mut value = &rest[position + width..];
                        if value.starts_with(b"=") {
                            value = &value[1..];
                        }
                        if value.is_empty() {
                            pending = Some((opt, None));
                        } else {
                            store(opt, Some(Raw::new(value)), &mut values);
                        }
                        break;
                    }
                    position += width;
                }
            }
        } else {
            if positional_seen {
                fail_positional(lossy);
            }
            resolve(&mut pending, &mut positional, &mut positional_parsed, &mut values);
            positional = Some(Raw::new(bytes));
            positional_seen = true;
        }
        index += 1;
    }
    resolve(&mut pending, &mut positional, &mut positional_parsed, &mut values);
    Config::from(values, positional)
}
