        integer('p', "--places", &config.places)?
    } else {
        None
    };
    if let Some(len) = integer('u', "--func", &config.func)? {
        let places = places.unwrap_or(function_output::DEFAULT_PLACES);
        function_output::wave(len, places);
        return Ok(());
    }
    let mut file = match &config.inputfile {
        Some(path) => Some(io::BufReader::new(std::fs::File::open(path)?)),
        None => None,
    };
    let cols = integer('c', "--cols", &config.cols)?;
    let limit = match integer('l', "--len", &config.len)? {
        Some(0) => None,
        other => other,
    };
    let data = match file.as_mut() {
        Some(reader) => read_to_limit(reader, limit)?,
        None => {
