#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn octet_is_rendered_in_every_style() {
        assert_eq!(octet(0x61, OctetFormat::LowerHex, true), "0x61");
        assert_eq!(octet(0x61, OctetFormat::LowerHex, false), "61");
        assert_eq!(octet(0xab, OctetFormat::UpperHex, true), "0xAB");
        assert_eq!(octet(0x01, OctetFormat::Octal, true), "0o0001");
        assert_eq!(octet(0xff, OctetFormat::Octal, false), "0377");
        assert_eq!(octet(0x0a, OctetFormat::Binary, true), "0b00001010");
    }

    #[test]
    fn printable_text_falls_back_to_a_dot() {
        assert_eq!(printable(b'a'), 'a');
        assert_eq!(printable(b' '), ' ');
        assert_eq!(printable(0x1f), '.');
        assert_eq!(printable(0x7f), '.');
    }

    #[test]
    fn offsets_are_padded_to_six_digits() {
        assert_eq!(address(0), "000000");
        assert_eq!(address(0x1000), "001000");
        assert_eq!(address(0x100000), "100000");
        assert_eq!(address(0x1000004), "1000004");
    }

    #[test]
    fn every_byte_but_zero_is_its_own_color() {
        assert_eq!(tint(0x41), 0x41);
        assert_eq!(tint(0), 22);
    }

    #[test]
    fn options_are_found_by_short_and_long_name() {
        assert_eq!(find_long("cols"), Some(IDX_COLS));
        assert_eq!(find_long("nope"), None);
        assert_eq!(find_short('V'), Some(IDX_VERSION));
        assert_eq!(find_short('v'), None);
    }

    #[test]
    fn suggestions_prefer_the_last_declared_candidate() {
        assert_eq!(did_you_mean("p", &["places", "prefix"]), Some("prefix"));
        assert_eq!(did_you_mean("u", &["func"]), Some("func"));
        assert_eq!(did_you_mean("t", &["format", "color"]), None);
    }
}
EOF
